static int CmpStem(const void* key, const void* elem)
{
	return _stricmp((const char*)key, *(const char* const*)elem);
}

int CEmuArchiveIsSupported(const char* archive)
{
	char stem[128];
	const char* comma;
	size_t n;

	if (!archive || !archive[0]) return 0;
	/* Catalog rows can carry "stem,companion"; the triage report keys on the
	   zip stem alone. */
	comma = strchr(archive, ',');
	n = comma ? (size_t)(comma - archive) : strlen(archive);
	if (n >= sizeof(stem)) return 0;
	memcpy(stem, archive, n);
	stem[n] = 0;

	return bsearch(stem, kSupported,
		sizeof(kSupported) / sizeof(kSupported[0]),
		sizeof(kSupported[0]), CmpStem) ? 1 : 0;
}

int CEmuSupportedArchiveCount(void)
{
	return (int)(sizeof(kSupported) / sizeof(kSupported[0]));
}
